args:
set -euo pipefail
case "$$PLAYWRIGHT_SUITE" in
  smoke) suite_command="test:e2e:smoke" ;;
  full) suite_command="test:e2e" ;;
  *) echo "_PLAYWRIGHT_SUITE must be exactly smoke or full." >&2; exit 1 ;;
esac
corepack enable
pnpm exec playwright install --with-deps chromium
command -v pnpm
pnpm run "$$suite_command"
